      "id": "global-5",
      "key": "루브르 박물관 (Musée du Louvre)",
      "city": "Paris, France",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The Louvre evolved from a medieval fortress into a palace of the French kings; in 1528 François I decided to demolish its medieval keep, and in 1546 appointed Pierre Lescot to lead a palace rebuilding project. In the late 16th century, under Henri IV, the Grande Galerie was built to link the Louvre with the Tuileries Palace, and the palace opened as a public art museum in 1793. Today, the Renaissance Salle des Caryatides displays sculpted female figures serving as columns, while the Grande Galerie is marked by its arches, columns and skylights.",
        "ja": "ルーヴルは中世の要塞からフランス王の宮殿へと変わり、1528年にフランソワ1世が中世の主塔の取り壊しを決め、1546年にはピエール・レスコに宮殿再建を委ねました。16世紀末、アンリ4世の時代にルーヴル宮とチュイルリー宮を結ぶグランド・ギャラリーが建設され、1793年に宮殿は公立美術館として開館しました。現在、ルネサンス様式のカリアティードの間では柱として彫られた女性像を、グランド・ギャラリーではアーチや柱、天窓を見ることができます。",
        "ko": "루브르는 중세의 요새에서 프랑스 왕들의 궁전으로 바뀌었고, 프랑수아 1세는 1528년 중세 성채를 허물기로 했으며 1546년 피에르 레스코에게 궁전 재건을 맡겼습니다. 앙리 4세 치하인 16세기 말에는 루브르와 튈르리 궁전을 잇는 그랑드 갤러리가 세워졌고, 1793년 루브르 궁전은 공공 미술관으로 문을 열었습니다. 오늘날 르네상스 양식의 카리아티드 홀에서는 조각된 여성 기둥상을 볼 수 있으며, 그랑드 갤러리에는 아치와 기둥, 채광창이 이어집니다.",
        "zh": "卢浮宫从中世纪堡垒演变为法国王宫；1528年，弗朗索瓦一世决定拆除其中世纪主塔，并于1546年委任皮埃尔·莱斯科主持宫殿改建。16世纪末，亨利四世时期建成连接卢浮宫与杜伊勒里宫的大画廊；1793年，卢浮宫宫殿作为公共美术馆开放。如今，文艺复兴风格的女像柱厅可见作为柱子的雕刻女性像，大画廊则保留了拱券、柱列与天窗。"
      },
