      "id": "global-6",
      "key": "오르세 미술관 (Musée d'Orsay)",
      "city": "파리, 프랑스",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Designed and built from 1898 by Victor Laloux as a railway station and hotel, the Orsay building opened on 14 July 1900 for the Paris Universal Exposition. After 1939 it served only suburban trains; in 1977 its conversion into a museum for art of the second half of the 19th century was decided, and the Musée d’Orsay opened on 1 December 1986. Today it presents art from 1848 to 1914 across several disciplines, while the tall former station hall, glass roof and metal structure behind the stone façade remain visible features of its railway architecture.",
        "ja": "オルセーの建物は、ヴィクトール・ラルーの設計で1898年から駅とホテルとして建設され、パリ万国博覧会に合わせて1900年7月14日に開業した。1939年以降は郊外列車の駅となり、1977年に19世紀後半の美術を扱う美術館への転用が決まり、1986年12月1日にオルセー美術館が開館した。現在は1848年から1914年までの複数の芸術分野を紹介しており、高い旧駅舎のホール、ガラス屋根、石造りの外壁に覆われた金属構造に、鉄道建築の特徴を見ることができる。",
        "ko": "오르세 미술관 건물은 빅토르 랄루가 1898년부터 설계·건축한 역과 호텔로, 1900년 7월 14일 파리 만국박람회에 맞춰 문을 열었다. 역은 1939년 이후 교외 열차역으로만 쓰였으며, 1977년 19세기 후반 예술을 위한 미술관으로 전환하기로 결정되어 1986년 12월 1일 오르세 미술관이 개관했다. 오늘날 이곳은 1848~1914년의 여러 예술 분야를 다루며, 현장에서는 높은 역 홀과 유리 지붕, 석재 외벽 뒤의 금속 구조에서 옛 철도 건물의 특징을 볼 수 있다.",
        "zh": "奥赛建筑由维克多·拉卢设计，自1898年起作为火车站和酒店兴建，并于1900年7月14日配合巴黎世界博览会启用。1939年后，这里仅承担郊区铁路服务；1977年决定将其改建为展示19世纪后半叶艺术的博物馆，奥赛博物馆于1986年12月1日开馆。如今馆内呈现1848至1914年的多类艺术，现场仍可看到高耸的旧站大厅、玻璃屋顶，以及石质外墙后方的金属结构等铁路建筑特征。"
      },
