      "id": "global-7",
      "key": "로마 콜로세움 (Colosseum)",
      "city": "Rome, Italy",
      "priority": "planned-italy",
      "kind": "global-landmark",
      "history": {
        "en": "Commissioned by emperors of the Flavian dynasty and built in the 1st century CE, the amphitheatre hosted public spectacles such as animal hunts and gladiatorial contests. After gladiatorial games were abolished in late antiquity, it declined; in the Middle Ages and Renaissance it was quarried for building materials and also accommodated workshops and homes. Today, visitors can see its layered interior spaces and the arches framing views of the city.",
        "ja": "フラウィウス朝の皇帝たちの命で西暦1世紀に建てられたこの円形闘技場では、猛獣狩りや剣闘士競技などの公開興行が行われました。古代末期に剣闘士競技が廃止されると衰退し、中世からルネサンス期には建築材の採石場となったほか、作業場や住居にも使われました。現在は、時代ごとの痕跡をとどめる内部空間と、街を望む外周のアーチを見ることができます。",
        "ko": "플라비우스 왕조 황제들의 명으로 서기 1세기에 세워진 이 원형경기장은 동물 사냥과 검투 경기 같은 대중 공연에 쓰였습니다. 고대 말 검투 경기가 폐지된 뒤 쇠퇴했고, 중세와 르네상스에는 건축 자재 채석장으로 쓰이는 한편 작업장과 주거 공간도 들어섰습니다. 오늘날에는 서로 다른 시대의 흔적이 남은 내부 공간과 도시를 내다볼 수 있는 외벽 아치가 보입니다.",
        "zh": "这座圆形竞技场由弗拉维王朝皇帝下令于公元1世纪建造，曾举办猎兽和角斗等公共表演。古代晚期角斗表演废止后，建筑逐渐衰落；中世纪至文艺复兴时期，它被用作建筑材料采石场，也容纳过作坊和住宅。如今仍可看到保留不同时期痕迹的内部空间，以及外墙拱门映衬下的城市景观。"
      },
