      "id": "global-10",
      "key": "베네치아 산 마르코 광장 & 대운하",
      "city": "베네치아, 이탈리아",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Venice’s lagoon-island settlements took shape around the 5th century, and by the 10th century the city had become a major maritime power. The Grand Canal is the central waterway in the city’s canal network, while St Mark’s Square gathers major monuments of the Republic, including the basilica and Doge’s Palace. The first church of San Marco was consecrated in 832; construction of the present basilica began in 1063 and it was consecrated in 1094, while the Doge’s Palace wing facing the square took its present form from 1424 onward. On site, the basilica’s mosaics and the palace’s layered Gothic and Renaissance architecture are visible.",
        "ja": "ヴェネツィアでは5世紀ごろ、潟の島々に集落が形成され、10世紀には主要な海洋勢力となった。大運河は市内の運河網の中心的な水路であり、サン・マルコ広場には大聖堂やドゥカーレ宮殿など共和国時代の主要建築が集まる。サン・マルコ最初の教会は832年に献堂され、現在の聖堂は1063年に再建が始まり1094年に献堂された一方、広場に面するドゥカーレ宮殿の翼は1424年以降に現在の形で築かれた。現地では聖堂のモザイク装飾と、宮殿に重なるゴシック様式・ルネサンス様式を確認できる。",
        "ko": "베네치아는 5세기 무렵 석호의 섬들에 정착지가 형성되었고, 10세기에는 주요 해상 세력으로 성장했다. 대운하는 도시 수로망의 중심 수로이며, 산 마르코 광장에는 대성당과 도제궁을 비롯한 공화국 시대의 건축군이 모여 있다. 대성당의 첫 교회는 832년에 봉헌되었고 현재 건물은 1063년에 재건이 시작되어 1094년에 봉헌되었으며, 광장 쪽 도제궁 날개는 1424년부터 현재 모습으로 지어졌다. 현장에서는 대성당의 모자이크 장식과 도제궁의 고딕·르네상스 양식이 겹쳐진 모습을 볼 수 있다.",
        "zh": "威尼斯的泻湖岛屿聚落约在5世纪形成，到10世纪已发展为重要海上力量。大运河是城内水道网络的主干，圣马可广场则汇集了圣马可大教堂、总督宫等共和国时期的重要建筑。圣马可最早的教堂于832年祝圣；现存教堂于1063年开始重建、1094年祝圣，而总督宫面向广场的翼楼自1424年起建成现有形制。现场可见大教堂的马赛克装饰，以及总督宫叠加呈现的哥特式与文艺复兴风格。"
      },
