      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Porto’s hills overlook the mouth of the Douro, forming a historic urban landscape closely tied to the river; the bridge extends that heritage across to the opposite bank. The iron Dom Luís I Bridge, associated with designers Théophile Seyrig and Joaquim de Matos, opened in 1886 and connects parts of Porto and Vila Nova de Gaia. The area entered the UNESCO World Heritage List in 1996, and in 2016 the listed property’s name was amended to explicitly include the bridge and the Monastery of Serra do Pilar. On site, the iron bridge spans the river within the hillside cityscape.",
        "ja": "ドウロ川河口を見下ろす丘に広がるポルトは、川と結びついた歴史的な都市景観を形成し、橋はその遺産を対岸へと延ばしています。テオフィル・セイリグとジョアキン・デ・マトスが設計に関わった鉄橋、ドン・ルイス1世橋は1886年に開通し、ポルトとヴィラ・ノヴァ・デ・ガイアの各所を結びます。この一帯は1996年にユネスコ世界遺産に登録され、2016年には登録資産の名称に橋とセラ・ド・ピラール修道院が明記されました。現地では、川を横切る鉄橋と両岸の丘陵市街を望めます。",
        "ko": "도루강 하구를 내려다보는 언덕에 자리한 포르투는 강과 연결된 오랜 도시 경관을 이루며, 다리는 그 역사 지구를 강 건너편까지 잇습니다. 테오필 세리그와 조아킹 드 마투스가 설계에 참여한 철제 동 루이스 1세 다리는 1886년에 개통되어 포르투와 빌라노바드가이아의 여러 지점을 연결합니다. 이 일대는 1996년 유네스코 세계유산에 등재됐고, 2016년 등재 명칭에 다리와 세라 두 필라르 수도원이 명시됐습니다. 현장에서는 강을 가로지르는 철제 다리와 양쪽 언덕의 도시 경관을 볼 수 있습니다.",
        "zh": "波尔图依山而建，俯瞰杜罗河入海口，形成与河流紧密相连的历史城市景观；这座桥将相关遗产延伸至河对岸。由泰奥菲尔·塞里格和若阿金·德·马托斯参与设计的铁质唐路易一世桥于1886年通车，连接波尔图与加亚新城的多个地点。该区域于1996年列入联合国教科文组织世界遗产名录，2016年遗产名称修订后明确纳入此桥和塞拉杜皮拉尔修道院。现场可见铁桥横跨河面，并与两岸山坡城市景观相连。"
      },
