      "id": "global-12",
      "key": "제로니무스 수도원 & 벨렝탑",
      "city": "리스본",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "In 1496, King Manuel I requested papal authorization for a monastery by the Tagus estuary; construction began around 1501 and was completed roughly a century later. The monastery’s Hieronymite monks were assigned to pray for the king and provide spiritual assistance to sailors leaving Lisbon, while nearby Belém Tower was built in 1514–1520 to defend the port. On site, the monastery preserves its 16th-century cloister and refectory, and visitors can see Manueline stonework combining late Gothic and Renaissance elements, including carved ropes, armillary spheres and crosses of the Order of Christ, as well as the tower’s artillery bastion.",
        "ja": "マヌエル1世は1496年、テージョ川河口近くに修道院を建てる許可を教皇庁に求め、工事は1501年ごろに始まり、約1世紀後に完成しました。修道院の聖ヒエロニムス会修道士は王のために祈り、リスボンを出航する船乗りに精神的な支援を行うこととされ、近くのベレンの塔は港の防衛のため1514～1520年に建設されました。現地には16世紀の回廊と食堂が残り、後期ゴシックとルネサンスの要素を合わせたマヌエル様式の石彫、彫刻された綱・天球儀・キリスト騎士団の十字架、砲台を備えた塔を見ることができます。",
        "ko": "마누엘 1세는 1496년 교황청에 타구스강 어귀의 수도원 건립 허가를 요청했고, 공사는 1501년경 시작되어 약 한 세기 뒤 마무리됐다. 수도원의 성 히에로니무스회 수도사들은 왕을 위해 기도하고 리스본을 떠나는 선원들에게 영적 도움을 주도록 배치됐으며, 인근 벨렝탑은 항구 방어를 위해 1514~1520년에 세워졌다. 현장에는 16세기 수도원 회랑과 식당, 후기 고딕·르네상스 요소가 섞인 마누엘 양식 석조 장식, 밧줄·천체구·그리스도 기사단 십자가 장식과 포대 구조를 갖춘 탑이 남아 있다.",
        "zh": "曼努埃尔一世于1496年向教廷申请在塔霍河口附近建造修道院，工程约于1501年开始，并在约一个世纪后完成。修道院的圣热罗尼莫会修士奉命为国王祈祷，并为离开里斯本的船员提供精神帮助；附近的贝伦塔则于1514至1520年间建成，用于防卫港口。现场仍可见修道院的16世纪回廊和食堂，以及融合晚期哥特式与文艺复兴元素的曼努埃尔式石雕；塔上有绳索、浑天仪和基督骑士团十字等装饰，并设有炮台结构。"
      },
