      "key": "비엔나 쇤브룬 궁전 & 정원 (Schönbrunn)",
      "city": "비엔나, 오스트리아",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "A small Habsburg hunting lodge and later summer residence stood here; after its destruction in 1683, rebuilding began and the project grew into an imperial summer residence for the court. Schönbrunn served as the Habsburg emperors’ residence from the 18th century until 1918, with successive rulers modifying its buildings and gardens; it became Austrian Republic property after 1918. Today the Baroque palace and gardens, including the Gloriette, Roman ruins, statuary and decorated imperial rooms, preserve the ensemble of architecture, landscape design and decorative art.",
        "ja": "ここにはハプスブルク家の小さな狩猟館と夏の居所があり、1683年の破壊後に再建が始まり、宮廷の皇帝の夏の離宮へと計画が拡大した。シェーンブルンは18世紀から1918年までハプスブルク皇帝の居所で、歴代君主の好みに応じて建物と庭園が改修され、1918年以降はオーストリア共和国の所有となった。現在はバロック様式の宮殿と庭園に、グロリエッテ、ローマ風遺跡、彫像、装飾豊かな皇帝の部屋が残り、建築・庭園設計・装飾芸術の一体性を伝えている。",
        "ko": "이곳에는 합스부르크가의 작은 사냥용 별장과 여름 거처가 있었으며, 1683년 파괴된 뒤 재건 공사가 시작되어 궁정의 제국 여름 궁전으로 확대되었다. 18세기부터 1918년까지 합스부르크 황제의 거처였고, 여러 군주의 취향에 따라 건물과 정원이 바뀌었으며 1918년 이후 오스트리아 공화국 소유가 되었다. 오늘날 현장에는 바로크 궁전과 정원, 글로리에테·로마 유적·조각상 및 장식된 황실 공간이 남아 있어 건축·정원·장식 예술이 결합된 유산의 모습을 보여 준다.",
        "zh": "这里曾有哈布斯堡家族的一座小型狩猎别墅，后来成为夏季居所；建筑在1683年遭毁后开始重建，工程逐步扩展为宫廷的皇家夏宫。申布伦自18世纪起至1918年一直是哈布斯堡皇帝的居所，历代君主依其偏好改造建筑与花园；1918年后归奥地利共和国所有。如今可见的巴洛克宫殿与花园、格洛丽埃特、罗马式遗迹、雕像及装饰华美的皇室房间，共同呈现建筑、园林设计与装饰艺术融为一体的遗产。"
      },
