      "id": "global-16",
      "key": "마추픽추 공중도시 (Machu Picchu)",
      "city": "Cusco, Peru",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The Inca city of Machu Picchu was planned and built around 1450 under the rule of the Inca Pachakuti, according to Cusco’s cultural authority, as a religious, political, and administrative center. It was abandoned in the second half of the 16th century, though visits and occasional habitation continued; it became widely known outside the region after Hiram Bingham’s 1911 visit. Its ridge-top remains include upper and lower zones separating residential and agricultural areas, a central square, stone terraces, and massive walls and ramps.",
        "ja": "クスコの文化当局によると、インカの都市マチュピチュは約1450年、インカ王パチャクティの治世に計画・建設され、宗教・政治・行政の中心地とされました。16世紀後半に放棄されましたが、その後も時折訪問や居住があり、1911年のハイラム・ビンガムの訪問を経て域外に広く知られるようになりました。尾根上の遺構には、居住域と農耕域を分ける上部・下部の区画と中央広場、石造テラス、大規模な石壁や傾斜路が残っています。",
        "ko": "잉카 도시 마추픽추는 쿠스코 문화 당국에 따르면 약 1450년 잉카 파차쿠티의 통치기에 계획·건설되었으며, 종교·정치·행정 중심지로 조성되었습니다. 16세기 후반 버려졌지만 이곳은 방문·거주가 간헐적으로 이어졌고, 1911년 히람 빙엄의 방문 이후 외부에 널리 알려졌습니다. 산등성이의 유적에는 농경 구역과 주거 구역을 나눈 상·하부 구획과 중앙 광장, 돌 테라스와 거대한 석벽·경사로가 남아 있습니다.",
        "zh": "据库斯科文化主管机构介绍，印加城市马丘比丘约于1450年在印加统治者帕查库蒂时期规划和建造，作为宗教、政治与行政中心。它在16世纪后半叶被废弃，但此后仍有人偶尔到访和居住；1911年希拉姆·宾厄姆到访后，它才广为外界所知。山脊遗址保留了划分居住区与农业区的上下分区和中央广场，以及石砌梯田、厚重石墙和坡道。"
      },
