      "key": "구엘 공원 (Park Güell)",
      "city": "Barcelona, Spain",
      "priority": "planned-core",
      "kind": "global-landmark",
      "history": {
        "en": "In 1900, businessman Eusebi Güell commissioned Antoni Gaudí to design a garden suburb for affluent families; Gaudí planned paths, viaducts, steps and water systems adapted to the sloping site. Sales and development fell short, and work stopped in 1914, with only two of the 60 planned houses built. After Güell’s heirs offered the estate, Barcelona City Council approved its purchase in 1922, and it opened as a public park in 1926. Visitors can see the entrance porter’s lodge, monumental steps, the columned Hypostyle Room and a tiled bench; Gaudí’s works were inscribed on UNESCO’s World Heritage List in 1984.",
        "ja": "1900年、実業家エウセビ・グエイは富裕層向けの庭園付き住宅地を構想し、アントニ・ガウディに設計を依頼しました。ガウディは傾斜地に合わせて道、高架橋、階段、水管理施設を計画しましたが、分譲は振るわず、工事は1914年に中止され、計画された60戸のうち建設されたのは2戸でした。グエイの相続人による売却提案を受け、バルセロナ市は1922年に購入を承認し、1926年に公園として一般公開しました。現地では入口の管理人住宅、階段、柱が並ぶ列柱ホール、タイル張りのベンチを見られ、ガウディ作品群は1984年にユネスコ世界遺産に登録されました。",
        "ko": "1900년 사업가 에우세비 구엘은 부유층을 위한 정원형 주거단지를 구상해 안토니 가우디에게 설계를 맡겼으며, 가우디는 경사진 지형에 맞춰 길·고가교·계단과 물 관리 체계를 계획했습니다. 분양과 개발은 기대에 미치지 못해 1914년 중단되었고, 계획된 60채 가운데 두 채만 지어졌습니다. 구엘의 상속인들이 시에 매각을 제안한 뒤 바르셀로나 시가 1922년 매입을 승인했고, 1926년 공공 공원으로 문을 열었습니다. 현장에는 입구의 관리인 주택과 계단, 기둥이 늘어선 히포스타일 홀, 타일 장식 벤치가 있으며, 가우디의 작품군은 1984년 유네스코 세계유산에 등재됐습니다.",
        "zh": "1900年，企业家尤塞比·圭尔委托安东尼·高迪为富裕家庭设计一处带花园的住宅区；高迪依照坡地规划道路、高架桥、阶梯和水利系统。由于销售和开发不理想，工程于1914年停止，原计划的60栋住宅仅建成两栋。圭尔的继承人提出出售后，巴塞罗那市议会于1922年批准购入，并于1926年将其开放为公园。园内可见入口守卫住宅、阶梯、柱廊厅和铺有瓷砖的长椅；高迪作品群于1984年列入联合国教科文组织《世界遗产名录》。"
      },
