      "id": "global-casa-batllo",
      "key": "카사 바트요 (Casa Batlló)",
      "city": "Barcelona, Spain",
      "priority": "planned-core",
      "kind": "global-landmark",
      "history": {
        "en": "The building on Barcelona’s Passeig de Gràcia was built by Emili Sala Cortés in 1877 and acquired in 1903 by textile industrialist Josep Batlló. Batlló commissioned Antoni Gaudí to remodel rather than demolish it; work in 1904–1906 transformed the façade and interior layout and enlarged the light well. After serving as a residential building, the house opened to the public in 1995; visible features include the blue-tiled light well designed to distribute daylight and the rooftop chimneys.",
        "ja": "バルセロナのグラシア通りにあるこの建物は、エミリ・サラ・コルテスが1877年に建て、繊維業者のジュゼップ・バッリョーが1903年に取得しました。バッリョーはアントニ・ガウディに建物の全面改修を依頼し、1904〜1906年の工事で、取り壊しではなく外観と室内の間取りを改め、採光井戸を広げました。住宅として使われた後、1995年に一般公開され、館内では自然光を行き渡らせる青系タイル張りの採光井戸や屋上の煙突を見ることができます。",
        "ko": "바르셀로나의 그라시아 대로에 있던 건물은 에밀리 살라 코르테스가 1877년에 지었고, 섬유업자 조셉 바트요가 1903년에 매입했습니다. 바트요는 안토니 가우디에게 건물 철거 대신 전면 개조를 맡겼으며, 공사는 1904~1906년에 진행되어 외관과 내부 구획이 바뀌고 채광정이 확장되었습니다. 이후 주거 건물로 쓰인 이 집은 1995년 대중에게 공개되었으며, 내부에서는 빛을 아래층까지 퍼뜨리도록 설계된 파란색 계열 타일의 채광정과 옥상의 굴뚝들을 볼 수 있습니다.",
        "zh": "这座位于巴塞罗那格拉西亚大道的建筑由埃米利·萨拉·科尔特斯于1877年建成，纺织业者何塞普·巴特略于1903年购入。巴特略委托安东尼·高迪全面改造而非拆除建筑；1904至1906年的工程改变了立面和室内布局，并扩大采光井。建筑此后作为住宅使用，1995年向公众开放；室内可见用于将自然光引入各层的蓝色瓷砖采光井，以及屋顶的烟囱。"
      },
