      "id": "global-casa-mila",
      "key": "카사 밀라 (Casa Milà / La Pedrera)",
      "city": "Barcelona, Spain",
      "priority": "planned-core",
      "kind": "global-landmark",
      "history": {
        "en": "Designed and built by Antoni Gaudí between 1906 and 1912, Casa Milà was his last civil work and contributed to the development of architecture and building technology in the late 19th and early 20th centuries. Built as an apartment building, it largely retains its original apartment design while also accommodating cultural, visitor and other uses today, according to UNESCO. Restoration has highlighted features including the roof, attic and “noble” floor; the property was inscribed on the World Heritage List in 1984.",
        "ja": "アントニ・ガウディが1906年から1912年に設計・建設したカサ・ミラは、彼の最後の民間建築作品であり、19世紀末から20世紀初頭の建築と建築技術の発展に寄与した。集合住宅として建てられ、ユネスコによれば、現在も元の集合住宅としての設計をおおむね保ちながら、文化・観光などの用途も受け入れている。修復では屋上、屋根裏、「ノーブル階」などの特徴が際立つようにされ、1984年に世界遺産に登録された。",
        "ko": "안토니 가우디가 1906~1912년에 설계·건축한 카사 밀라는 그의 마지막 민간 건축 작업으로, 19세기 말~20세기 초 건축과 건축기술 발전에 기여한 작품이다. 처음에는 아파트 주거용으로 지어졌으며, 유네스코는 건물이 원래 아파트 설계를 대체로 유지하면서 오늘날 문화·관광 등 다른 용도도 함께 수용한다고 설명한다. 복원 과정에서는 지붕, 다락, 주층(‘noble floor’) 같은 특징이 부각됐고, 1984년 세계유산으로 등재됐다.",
        "zh": "安东尼·高迪于1906至1912年设计并建造米拉之家；这是他的最后一项民用建筑作品，也体现了其对19世纪末至20世纪初建筑及建造技术发展的贡献。它最初是公寓住宅；据联合国教科文组织介绍，建筑大体保留了原有公寓设计，如今也兼有文化、旅游等用途。修复工程突出了屋顶、阁楼和“主层”等特色；该建筑于1984年列入世界遗产名录。"
      },
