      "id": "global-plaza-espana",
      "key": "세비야 스페인 광장 (Plaza de España)",
      "city": "Seville, Spain",
      "priority": "planned-core",
      "kind": "global-landmark",
      "history": {
        "en": "Seville’s Plaza de España was designed by architect Aníbal González for the 1929 Ibero-American Exhibition, with construction beginning in 1914. Its semi-elliptical regionalist building surrounds a canal and is lined with arcades; tiled benches along its curved wings depict scenes associated with Spain’s provinces. After the exhibition, it was intended to become a labor university, but instead housed public bodies including the Government Delegation in Andalusia.",
        "ja": "セビリアのスペイン広場は、建築家アニバル・ゴンサレスが1929年のイベロアメリカ博覧会のために設計し、建設は1914年に始まりました。地域主義建築による半楕円形の建物が運河を囲み、曲線状の翼部に並ぶタイル張りのベンチにはスペイン各地方に関する場面が描かれています。博覧会後は労働大学として使う構想でしたが、実際にはアンダルシア政府代表部などの公的機関が入居しました。",
        "ko": "세비야의 스페인 광장은 건축가 아니발 곤살레스가 1929년 이베로아메리카 박람회를 위해 설계했으며, 건설은 1914년에 시작되었습니다. 지역주의 건축 양식의 반타원형 건물은 아케이드와 운하를 둘러싸고, 곡선형 날개의 타일 벤치에는 스페인 여러 지방의 장면이 표현되어 있습니다. 박람회 뒤에는 노동대학으로 쓸 계획이었으나, 실제로는 안달루시아 정부 대표부 등 공공기관들이 자리했습니다.",
        "zh": "塞维利亚西班牙广场由建筑师安尼巴尔·冈萨雷斯为1929年伊比利亚美洲博览会设计，工程始于1914年。其半椭圆形的地方主义风格建筑环绕运河，弧形翼楼旁的瓷砖长椅描绘了与西班牙各地区有关的场景。博览会后原计划将其用作劳动大学，实际则由安达卢西亚政府代表处等公共机构入驻。"
      },
