      "id": "global-puente-nuevo-ronda",
      "key": "론다 누에보 다리 & 헤밍웨이 산책로 (Puente Nuevo)",
      "city": "론다, 스페인 (Ronda, Spain)",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The present Puente Nuevo is a stone bridge built to connect Ronda’s old quarter with the Mercadillo district across the Tajo gorge; construction began in 1751 and it was completed in May 1793. Architect José Martín de Aldehuela directed the work, using stone extracted from the gorge floor. From the bridge, visitors can see the gorge and houses perched at the cliff edge; the adjacent Hemingway Walk is described as a scenic walk beside the bridge.",
        "ja": "現在のプエンテ・ヌエボは、タホ渓谷で隔てられたロンダ旧市街とメルカディージョ地区を結ぶ石橋で、1751年に着工し、1793年5月に完成しました。建築家ホセ・マルティン・デ・アルデウエラが工事を指揮し、石材は渓谷の底から切り出されました。橋からは渓谷と崖の縁に建つ家々を望め、隣接するヘミングウェイ遊歩道は橋のそばの眺望散策路として紹介されています。",
        "ko": "현재의 푸엔테 누에보는 타호 협곡으로 갈라진 론다 구시가지와 메르카디요 지구를 잇기 위해 1751년에 공사를 시작해 1793년 5월에 완공한 석조 다리입니다. 건축가 호세 마르틴 데 알데우엘라가 공사를 이끌었으며, 다리의 석재는 협곡 바닥에서 채취했습니다. 다리 위에서는 협곡과 절벽 가장자리에 자리한 집들을 볼 수 있고, 인접한 헤밍웨이 산책로는 다리 옆 전망 산책길로 안내됩니다.",
        "zh": "现存的新桥是一座石桥，横跨塔霍峡谷，连接龙达老城区与梅尔卡迪略区；工程于1751年开工，1793年5月竣工。建筑师何塞·马丁·德·阿尔德韦拉主持工程，石料取自峡谷底部。从桥上可见峡谷以及建在悬崖边缘的房屋；官方资料将相邻的海明威步道介绍为桥旁的观景步道。"
      },
