      "id": "global-34",
      "key": "톨레도 대성당 & 알카사르 (Toledo Cathedral)",
      "city": "톨레도, 스페인",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Toledo Cathedral began in 1226, promoted by Ferdinand III and Archbishop Rodrigo Jiménez de Rada on the site of an earlier Visigothic church and the city’s Great Mosque; it was consecrated in 1493. Built over more than two centuries, it is a Gothic church whose interior includes five naves, a broad transept, an ambulatory, and radial chapels. The Alcázar occupies a site with remains of Roman defensive works; in 1535, under Charles V, it was substantially reshaped as a Renaissance palace and royal residence, then destroyed during the 1936 Civil War and rebuilt in the mid-20th century. Today the building houses Army Museum displays, and its visible features include corner towers and a central courtyard with galleries.",
        "ja": "トレド大聖堂は、旧西ゴート教会と市の大モスクがあった場所に、フェルナンド3世と大司教ロドリゴ・ヒメネス・デ・ラダの主導で1226年に着工し、1493年に献堂されたゴシック聖堂です。建設は2世紀以上続き、内部には五廊、広い翼廊、周歩廊、放射状の礼拝堂があります。アルカサルはローマ時代の防御施設の遺構が確認された場所にあり、1535年、カルロス5世の時代に王の居所となるルネサンス宮殿へ大きく改築されましたが、1936年の内戦で破壊され、20世紀半ばに再建されました。現在は陸軍博物館の展示が置かれ、外観では四隅の塔と、回廊を備えた中央中庭を見ることができます。",
        "ko": "톨레도 대성당은 옛 서고트 교회와 이슬람 대모스크가 있던 자리에 1226년 페르난도 3세와 대주교 로드리고 히메네스 데 라다의 주도로 착공해, 1493년 봉헌된 고딕 성당입니다. 공사는 2세기 넘게 이어졌으며, 내부에는 다섯 개의 신랑과 넓은 익랑, 회랑식 통로와 방사형 예배당이 있습니다. 알카사르는 로마 시대 방어시설의 흔적을 간직한 요새 터로, 1535년 카를로스 5세 때 왕실 거처로 쓰일 르네상스 궁전으로 크게 개조됐고 1936년 전쟁으로 파괴된 뒤 20세기 중반 재건됐습니다. 오늘날 그 건물 안에서는 육군박물관 전시를 볼 수 있고, 외관에는 네 모서리 탑과 중앙 안뜰·회랑이 드러납니다.",
        "zh": "托莱多主教座堂于1226年在旧西哥特教堂和城中大清真寺的遗址上动工，由费尔南多三世和大主教罗德里戈·希门尼斯·德·拉达推动，并于1493年祝圣。工程历时两个多世纪；这座哥特式教堂内部有五个中殿、宽阔的横厅、环廊和放射状礼拜堂。阿尔卡萨尔所在地点留有罗马时期防御设施的遗迹；1535年，在卡洛斯五世时期，它被大规模改建为文艺复兴风格的王室居所，后在1936年内战中被毁，并于20世纪中叶重建。如今楼内设有陆军博物馆展览，外观可见四角塔楼以及带廊道的中央庭院。"
      },
