      "id": "global-35",
      "key": "산티아고 데 콤포스텔라 대성당 (Santiago Cathedral)",
      "city": "산티아고 데 콤포스텔라, 갈리시아, 스페인",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Built at a pilgrimage site associated with the tomb of St James, the medieval cathedral began in the Romanesque style in 1075 under Alfonso VI; work slowed for a time, resumed around 1100, and continued through the 12th century. Master Mateo was commissioned to complete the western part in 1168, and the cathedral was consecrated in 1211. The medieval structure was substantially altered in the Renaissance and Baroque periods; work on the present Baroque west façade began in 1738. Inside, the Pórtico de la Gloria combines Romanesque sculpture with features marking a transition toward Gothic art, while outside the south, the Platerías façade is the cathedral’s only surviving Romanesque façade.",
        "ja": "聖ヤコブの墓に結びつく巡礼地に建てられた中世の大聖堂は、アルフォンソ6世の時代の1075年にロマネスク様式で着工し、一時停滞した後、1100年頃に工事が再開され、12世紀を通じて進められました。1168年にはマテオ親方が西側部分の完成を委ねられ、大聖堂は1211年に献堂されました。中世の構造を基礎としながら、ルネサンス期・バロック期にも大きく改変され、現在の西側バロック様式のファサードは1738年に着工しました。内部の「栄光のポルティコ」はロマネスク彫刻とゴシックへの移行を示し、南側外部には大聖堂に残る唯一のロマネスク様式のファサード、プラテリアスがあります。",
        "ko": "성 야고보의 무덤을 중심으로 한 순례지에 세워진 중세 대성당은 알폰소 6세 시대인 1075년 로마네스크 양식으로 착공했고, 공사는 한동안 늦춰졌다가 1100년경 재개되어 12세기 내내 이어졌습니다. 1168년 마테오 장인이 서쪽 부분의 완공을 맡았으며, 대성당은 1211년 봉헌되었습니다. 중세 구조를 바탕으로 르네상스·바로크 시기에도 크게 바뀌어 서쪽의 현재 바로크 파사드는 1738년에 공사가 시작됐습니다. 안쪽에는 로마네스크 조각과 고딕으로의 이행 양식을 보여주는 영광의 문이 있고, 바깥 남쪽에는 대성당에 남은 유일한 로마네스크 파사드인 플라테리아스 파사드가 있습니다.",
        "zh": "这座中世纪大教堂建于与圣雅各墓相关的朝圣地，1075年在阿方索六世统治时期以罗曼式风格动工；工程一度放缓，约1100年恢复，并持续贯穿12世纪。1168年，马特奥大师受命完成西侧部分，大教堂于1211年举行祝圣仪式。建筑以中世纪结构为基础，又在文艺复兴和巴洛克时期经历显著改造；现存西立面的巴洛克工程始于1738年。内部的“荣耀门廊”呈现罗曼式雕刻及向哥特式过渡的特点；南侧外部的银匠门廊则是大教堂唯一留存的罗曼式立面。"
      },
