      "id": "global-44",
      "key": "신트라 페나 국립 왕궁 (Palácio Nacional da Pena)",
      "city": "신트라, 포르투갈",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "A chapel stood on this site by the 12th century, and in 1503 King Manuel I ordered the Royal Monastery of Our Lady of Pena to be built here. The 1755 earthquake damaged the monastery, which was abandoned after religious orders were dissolved in 1834. Ferdinand II bought it in 1838, expanded an initial restoration plan, and had a palace developed in the mid-19th century under the supervision of Wilhelm Ludwig von Eschwege. The former monastery’s church and cloister survive; the cloister’s Hispano-Mudéjar tiles, dating to 1511, and Gothic, Moorish, and Manueline references in the palace reveal its Romantic eclecticism.",
        "ja": "この場所には12世紀までに礼拝堂が建てられ、1503年にマヌエル1世がペナの聖母王立修道院の建設を命じた。1755年の地震で修道院は損傷し、1834年の修道会解散後に放棄された。フェルナンド2世は1838年に修道院を購入し、当初の修復計画を拡大して、19世紀半ばにヴィルヘルム・ルートヴィヒ・フォン・エシュヴェーゲの監督のもと宮殿を整備した。旧修道院の教会と回廊が残り、1511年の回廊に見られるヒスパノ・ムデハル様式のタイルと、宮殿のゴシック、ムーア、マヌエル様式の要素が、ロマン主義的な折衷建築を伝えている。",
        "ko": "이곳에는 12세기 예배당이 있었고, 마누엘 1세는 1503년 페나의 왕립 수도원을 세우도록 했다. 1755년 지진으로 수도원이 훼손되었으며, 1834년 수도회 해산 뒤 버려졌다. 페르난두 2세는 1838년 수도원을 사들여 처음의 복원 구상을 확장했고, 19세기 중엽 빌헬름 루트비히 폰 에슈베게의 감독 아래 궁전을 조성했다. 옛 수도원의 교회와 회랑이 남아 있으며, 1511년 회랑의 히스파노-무데하르 타일과 궁전의 고딕·무어·마누엘 양식 요소가 낭만주의적 혼합 건축을 보여준다.",
        "zh": "这里至少在12世纪已有一座小礼拜堂；1503年，曼努埃尔一世下令在此建造佩纳圣母皇家修道院。1755年地震损坏了修道院；1834年修会解散后，修道院被弃置。费迪南德二世于1838年购入修道院，将最初的修复计划扩展为宫殿营建，并于19世纪中叶在威廉·路德维希·冯·埃施韦格监督下推进工程。旧修道院的教堂和回廊仍然留存；建于1511年的回廊饰有西班牙—穆德哈尔风格瓷砖，宫殿则融入哥特、摩尔和曼努埃尔式元素，体现浪漫主义折衷风格。"
      },
