      "id": "global-45",
      "key": "헤갈레이라 별장 (Quinta da Regaleira)",
      "city": "Sintra, Portugal",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The estate’s recorded beginnings date to land known as Quinta da Torre in 1697; it came to be called Quinta da Regaleira in the 19th century. António Augusto de Carvalho Monteiro, owner from 1892, and Italian architect Luigi Manini led its transformation, with the principal works carried out between 1904 and 1910. The grounds bring together a palace, chapel, towers, underground passages and a well, caves, lakes and gardens, in a mix of revival styles including Manueline. Sold in 1945, the property was later acquired by the Municipality of Sintra, which undertook its gradual restoration and opened it to the public.",
        "ja": "この邸宅の起源は、1697年に「キンタ・ダ・トーレ」と記録された土地にさかのぼり、19世紀にはキンタ・ダ・レガレイラと呼ばれるようになった。1892年に所有者となったアントニオ・アウグスト・デ・カルヴァーリョ・モンテイロと、イタリア人建築家ルイジ・マニーニが再整備を主導し、主要な工事は1904～1910年に行われた。敷地には宮殿、礼拝堂、塔、地下通路と井戸、洞窟、池、庭園があり、マヌエル様式を含む複数の歴史主義様式が組み合わされている。1945年に売却された後、シントラ市が取得し、段階的に修復して一般公開した。",
        "ko": "오늘날의 별장은 1697년 ‘퀸타 다 토레’라는 이름으로 기록된 토지에서 비롯되었고, 19세기에 퀸타 다 헤갈레이라로 불리게 되었다. 1892년 소유주가 된 안토니우 아우구스투 카르발류 몬테이루와 이탈리아 건축가 루이지 마니니가 재구성을 이끌었으며, 주요 공사는 1904~1910년에 진행되었다. 궁전과 예배당, 탑, 지하 통로와 우물, 동굴·호수·정원이 한데 놓여 있고, 마누엘 양식 등 여러 역사주의 양식이 섞여 있다. 1945년 매각된 뒤 신트라 시가 인수해 점진적으로 복원하고 대중에 공개했다.",
        "zh": "这座庄园的可考历史可追溯至1697年，当时该地称为“托雷庄园”；19世纪改称雷加莱拉庄园。1892年成为业主的安东尼奥·奥古斯托·德·卡瓦略·蒙泰罗与意大利建筑师路易吉·马尼尼主导了改建，主要工程于1904至1910年间进行。园内汇集宫殿、礼拜堂、塔楼、地下通道与井、洞穴、湖池和花园，建筑融合了包括曼努埃尔风格在内的多种复古主义风格。庄园于1945年出售，后来由辛特拉市政府收购，逐步修复并向公众开放。"
      },
