      "id": "global-46",
      "key": "호카 곶 (Cabo da Roca)",
      "city": "신트라/카스카이스, 포르투갈",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Cabo da Roca, the westernmost point of mainland Europe, stands on coastal cliffs within the Sintra-Cascais Natural Park. Visit Portugal records a 17th-century fort here that guarded the entrance to Lisbon’s harbour and formed part of the coastal defences, especially during the Peninsular Wars; only traces remain today. One of the lighthouses ordered by a 1758 charter, Cabo da Roca Lighthouse began operating in 1772, and its white-tiled tower and red walkway are prominent features of the cape.",
        "ja": "ホカ岬はヨーロッパ大陸の最西端に位置し、シントラ・カスカイス自然公園内の海岸断崖にあります。Visit Portugalによると、17世紀にはリスボン港の入口を守る要塞があり、半島戦争期を中心に沿岸防衛の一部を担いましたが、現在はその痕跡だけが残っています。1758年の勅許で建設が命じられた灯台の一つであるホカ岬灯台は1772年に運用を開始し、白いタイル張りの塔と赤い通路が岬の目立つ構造物です。",
        "ko": "호카 곶은 유럽 대륙의 최서단으로, 신트라-카스카이스 자연공원 안의 해안 절벽에 자리한다. Visit Portugal은 17세기 이곳에 리스본 항구 입구를 지키는 요새가 있었고, 해안 방어선의 일부로 특히 반도 전쟁기에 역할했다고 기록하며 오늘날에는 흔적만 남았다고 설명한다. 1758년 칙령으로 건설이 추진된 등대 가운데 하나인 호카 곶 등대는 1772년 운영을 시작했으며, 현재 흰 타일 외벽과 붉은 난간의 탑이 곶에서 눈에 띈다.",
        "zh": "罗卡角是欧洲大陆最西端，位于辛特拉—卡斯凯什自然公园内的海岸峭壁上。葡萄牙旅游局记载，17世纪这里曾有一座守卫里斯本港入口的堡垒，属于沿海防线的一部分，并在半岛战争时期尤其发挥作用；如今仅存遗迹。罗卡角灯塔是1758年敕令下令兴建的灯塔之一，于1772年开始运行；其白色瓷砖塔身和红色步道是岬角上醒目的人工建筑。"
      },
