      "id": "global-47",
      "key": "오비두스 중세 성곽 마을 (Óbidos)",
      "city": "Óbidos, Portugal",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Archaeological finds in the municipality of Óbidos span from the Palaeolithic to the Roman period, but the origins of the hilltop fortress are uncertain; a Roman predecessor is only a possibility. Óbidos reappears in documentary records around the beginning of the 12th century, and under King Dinis, around the beginning of the 14th century, the town expanded beyond the walls and its defenses were reorganized. Today, the castle, winding lanes within the walls, Rua Direita linking the castle area with the town gate, white façades, and traces of Gothic, Renaissance, and Baroque architecture are visible. Much of the castle’s medieval-looking battlements and some towers and wall sections were reconstructed in the 1930s; whitewashing and street paving were made more uniform in the late 1940s.",
        "ja": "オビドス市域では旧石器時代からローマ時代までの遺跡が確認されていますが、丘上の要塞の起源は不明で、ローマ時代の先行施設があった可能性が示されるにとどまります。オビドスは12世紀初めごろの文献に再び現れ、ディニス王の時代、14世紀初めごろに城壁外へ市街が広がり、防御施設も改修されました。現在は城、城壁内の曲がりくねった街路、城と町の門を結ぶルア・ディレイタ、白い外壁、ゴシック・ルネサンス・バロック様式の痕跡を見ることができます。ただし、現在の中世風の胸壁や一部の塔・壁面の多くは1930年代の復元によるもので、1940年代後半には外壁の白塗りと道路舗装が統一されました。",
        "ko": "오비두스 자치구에서는 구석기 시대부터 로마 시대까지의 유적이 확인되지만, 성곽의 기원은 불분명하며 언덕 위 로마 요새가 선행했을 가능성만 제시됩니다. 오비두스는 12세기 초 무렵 문헌에 다시 나타나며, 디니스 왕 치세인 14세기 초 무렵 도시가 성벽 밖으로 확장되고 방어 시설도 정비되었습니다. 오늘날 성과 굽이진 성곽 안 거리, 성과 빌라 문을 잇는 루아 디레이타, 흰색 외벽과 고딕·르네상스·바로크 양식의 흔적을 볼 수 있습니다. 다만 현재 성곽의 중세풍 흉벽과 일부 탑·벽체는 1930년대 복원으로 다시 만들어졌고, 1940년대 후반에는 흰색 외벽과 거리 포장이 통일되었습니다.",
        "zh": "奥比杜什市镇发现了从旧石器时代到罗马时期的遗址，但山丘上堡垒的起源尚不明确；罗马时期曾有前身堡垒只是可能性之一。奥比杜什在约12世纪初重新见于文献；迪尼斯王统治时期、约14世纪初，城镇扩展到城墙之外，防御设施也得到调整。如今可见城堡、城墙内蜿蜒的街巷、连接城堡区域与城门的迪雷塔街、白色外墙，以及哥特式、文艺复兴和巴洛克风格的遗存。不过，现今许多中世纪风格的城垛及部分塔楼和墙段是20世纪30年代重建的；到40年代后期，外墙粉刷和街道铺面也趋于统一。"
      },
