      "kind": "global-landmark",
      "history": {
        "en": "Sainte-Chapelle was built in the mid-13th century by Louis IX as a palatine chapel in the royal palace on Paris’s Île de la Cité, to house relics of Christ’s Passion. Damaged during the French Revolution and no longer used for worship, it later served as a flour storehouse and an archive before a major restoration campaign in 1840–1863. In the upper chapel, visitors can see tall stained-glass windows depicting biblical narratives; about two-thirds of the glazing dates from the Middle Ages.",
        "ja": "サント・シャペルは13世紀半ば、ルイ9世がパリのシテ島にあった王宮内に、キリスト受難の聖遺物を納める宮廷礼拝堂として建てました。フランス革命期に損傷し、礼拝堂としての役割を失った後、小麦粉倉庫や文書保管所に使われ、1840～1863年に大規模な修復が行われました。上礼拝堂では聖書の物語を描く高いステンドグラスを見ることができ、その約3分の2は中世のものです。",
        "ko": "생트샤펠은 13세기 중엽 루이 9세가 파리 시테섬의 왕궁 안에 세운 궁정 예배당으로, 그리스도 수난의 유물을 보관하기 위해 마련했습니다. 프랑스혁명기에 손상되고 예배당 기능을 잃은 뒤 곡물 창고와 기록 보관소로 쓰였으며, 1840~1863년 대규모 복원을 거쳤습니다. 오늘날 상부 예배당에서는 성서 이야기를 담은 높은 스테인드글라스 창들을 볼 수 있으며, 그중 약 3분의 2는 중세 때의 것입니다.",
        "zh": "圣礼拜堂由路易九世于13世纪中叶建于巴黎西岱岛王宫内，作为宫廷礼拜堂供奉基督受难相关圣物。它在法国大革命期间受损并不再用于礼拜，后来曾作面粉仓库和档案库，1840至1863年间经历大规模修复。如今在上层礼拜堂可见描绘圣经故事的高大彩色玻璃窗，其中约三分之二为中世纪遗存。"
      },
