      "id": "global-55",
      "key": "베르사유 궁전 & 거울의 방 (Château de Versailles)",
      "city": "Versailles, France",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "In 1623, Louis XIII decided to build a small lodge at Versailles for hunting stays, and first used it in 1624. From 1661, Louis XIV greatly enlarged the palace and moved the court and government there in 1682. Created in the late 17th century, the Hall of Mirrors combines Jules Hardouin-Mansart’s architecture with ceiling paintings by Charles Le Brun; mirrored arcades face the windows. After the fall of the monarchy, the palace ceased to serve as a royal residence and was transformed into a museum in the early 19th century.",
        "ja": "ルイ13世は狩猟の滞在先として1623年に小さな館の建設を決め、1624年に初めて利用しました。ルイ14世は1661年から宮殿を大きく拡張し、1682年に宮廷と政府をヴェルサイユへ移しました。17世紀後半に造られた鏡の間は、ジュール・アルドゥアン＝マンサールの建築とシャルル・ル・ブランの天井画を備え、窓に向かい合う鏡のアーケードが特徴です。王政の終焉後、宮殿は王の住居としての役割を失い、19世紀初頭に博物館へ転用されました。",
        "ko": "루이 13세는 사냥터에 머물기 위해 1623년 작은 별궁 건설을 결정했고, 1624년 처음 이용했습니다. 루이 14세는 1661년부터 궁전을 크게 확장했으며, 1682년 궁정과 정부의 중심을 베르사유로 옮겼습니다. 17세기 후반 조성된 거울의 방은 쥘 아르두앵 망사르의 건축과 샤를 르 브룅의 천장화가 어우러지며, 창문 맞은편 거울 아케이드가 특징입니다. 왕정의 몰락 뒤 궁전은 왕실 거처 기능을 잃었고, 19세기 초 박물관으로 바뀌었습니다.",
        "zh": "路易十三于1623年决定在凡尔赛建造一座供狩猎时歇宿的小宅，并于1624年首次使用。路易十四从1661年起大规模扩建宫殿，并于1682年将宫廷和政府迁至此地。镜厅建于17世纪后期，融合了朱尔·阿尔杜安-曼萨尔的建筑设计与夏尔·勒布伦的天顶画，窗户对面排列着镜面拱廊。君主制覆灭后，宫殿不再作为王室居所，并于19世纪初改为博物馆。"
      },
