      "id": "global-59",
      "key": "에즈 빌라쥐 & 열대 정원 (Èze Village)",
      "city": "Èze, France",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Èze’s rocky promontory was inhabited from the Iron Age, and the Lords of Èze built a fortress there in the second half of the 12th century. Fortifications were strengthened under Savoyard rule, but French forces destroyed the castle and ramparts in 1706 during the War of the Spanish Succession. After the Second World War, Mayor André Gianton and Jean Gastaud of the Monaco Exotic Garden established a garden on the castle site; cacti, agaves, aloes, and castle remains are visible there today. The village’s Notre-Dame-de-l’Assomption church was built between 1764 and 1771 and was listed as a French Historic Monument in 1984.",
        "ja": "エズの岩山の岬には鉄器時代から人が住み、エズの領主は12世紀後半にここに城塞を築きました。サヴォイア統治下で防御施設が強化されましたが、スペイン継承戦争中の1706年にフランス軍が城と城壁を破壊しました。第二次世界大戦後、当時の市長アンドレ・ジアントンとモナコ熱帯植物園のジャン・ガストーが城跡に庭園を造り、現在はサボテン、リュウゼツラン、アロエや城塞の遺構を見ることができます。村のノートルダム・ド・ラソンプシオン教会は1764～1771年に建設され、1984年にフランスの歴史的建造物に指定されました。",
        "ko": "에즈의 바위 곶은 철기 시대부터 사람이 거주한 곳이며, 에즈 영주들은 12세기 후반 이곳에 성채를 세웠습니다. 사보이 통치기에는 요새와 마을 방어 시설이 보강되었지만, 1706년 스페인 왕위 계승 전쟁 중 프랑스군이 성과 성벽을 파괴했습니다. 제2차 세계대전 이후 성터에 앙드레 지앙통 시장과 모나코 열대 정원의 장 가스토가 협력해 정원을 조성했고, 현재 선인장·용설란·알로에와 성채 잔해를 볼 수 있습니다. 마을의 노트르담 드 라솜프시옹 성당은 1764~1771년에 지어졌으며 1984년 프랑스 역사기념물로 지정됐습니다.",
        "zh": "埃兹的岩石岬从铁器时代起便有人居住，埃兹领主于12世纪后半叶在此修建堡垒。萨伏依统治时期防御设施得到加强，但在西班牙王位继承战争期间，法国军队于1706年摧毁了城堡和城墙。第二次世界大战后，时任市长安德烈·吉安通与摩纳哥热带植物园的让·加斯托在城堡遗址上创建了花园；如今仍可见仙人掌、龙舌兰、芦荟和城堡遗迹。村中的圣母升天教堂建于1764至1771年，并于1984年列为法国历史古迹。"
      },
