      "key": "퐁 뒤 가르 (Pont du Gard)",
      "city": "Nîmes, France",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Built around the middle of the 1st century CE, the Pont du Gard formed part of a Roman aqueduct that carried water from a spring near Uzès to Nîmes. Its three-tier stone bridge crossed the Gardon; after the aqueduct ceased functioning around the early 6th century, the structure was adapted as a passage in the Middle Ages, and a road bridge was attached to its lower level in the 18th century. The stacked arcades and marks left on the stones by quarrying and cutting remain visible today.",
        "ja": "ポン・デュ・ガールは、ユゼス近郊の水源からニームへ水を運ぶローマ時代の水道橋の一部として、西暦1世紀中頃に築かれました。ガルドン川を渡る三層の石造水道橋は、水道が6世紀初め頃に使われなくなった後、中世には通行路として改変され、18世紀には古代橋の下段に道路橋が付設されました。現在も、重なるアーチと、石材に残る採石・加工の跡を見ることができます。",
        "ko": "퐁 뒤 가르는 우제스 인근의 샘에서 니메스까지 물을 보내던 로마 수로의 일부로, 서기 1세기 중엽 무렵 건설되었습니다. 가르동강을 건너도록 만든 3층 석조 수로교는 수로가 6세기 초 무렵 기능을 멈춘 뒤 중세에 통행로로 바뀌었고, 18세기에는 고대 다리의 아래층에 도로교가 덧붙었습니다. 오늘날에는 층층이 놓인 아치와 석재에 남은 채석·가공 흔적을 볼 수 있습니다.",
        "zh": "加尔桥约建于公元1世纪中叶，是罗马水道的一部分，用于将水从于泽斯附近的水源输送到尼姆。它以三层石砌结构跨越加尔东河；水道约在6世纪初停止使用后，桥体在中世纪被改作通道，18世纪又在古桥下层旁接建了公路桥。如今仍可看到层叠的拱券，以及石材上留下的采石和加工痕迹。"
      },
