      "id": "global-63",
      "key": "피렌체 우피치 미술관 (Gallerie degli Uffizi)",
      "city": "Florence, Italy",
      "priority": "optional-italy",
      "kind": "global-landmark",
      "history": {
        "en": "In the mid-16th century, Florence’s ruler Cosimo I de’ Medici commissioned Giorgio Vasari to bring the city’s administrative offices—the ‘uffizi’—together in one building; the Uffizi Palace was built between 1560 and 1580. It later housed the art collections of the Grand Dukes of Tuscany, and, following the 1737 bequest of Anna Maria Luisa de’ Medici, opened to the public as a museum in 1769 under Grand Duke Peter Leopold. Today the gallery occupies the building’s first and second floors, displaying paintings from the Middle Ages to the modern period alongside ancient sculpture, including Medici collections of antiquities in the corridors.",
        "ja": "16世紀半ば、フィレンツェを治めたコジモ1世・デ・メディチは、行政機関「ウフィーツィ」を一か所に集める建物をジョルジョ・ヴァザーリに依頼し、ウフィツィ宮殿は1560年から1580年にかけて建設されました。その後、トスカーナ大公家の美術品コレクションを収蔵し、アンナ・マリア・ルイーザ・デ・メディチの1737年の遺贈を経て、1769年に大公ピエトロ・レオポルドのもとで博物館として一般公開されました。現在、展示室は建物の1・2階にあり、中世から近代までの絵画や古代彫刻を展示し、回廊にはメディチ家の古代彫刻コレクションも並びます。",
        "ko": "피렌체의 통치자 코시모 1세 데 메디치는 16세기 중엽 조르조 바사리에게 행정 관청(‘우피치’)을 한데 모을 건물을 맡겼고, 우피치 궁전은 1560~1580년에 걸쳐 지어졌습니다. 이후 궁전은 토스카나 대공가의 미술품 소장처가 되었으며, 1737년 안나 마리아 루이자 데 메디치의 유증을 거쳐 1769년 피에트로 레오폴도 대공 때 대중에게 박물관으로 공개되었습니다. 오늘날 관람 공간은 건물의 1·2층에 자리하고, 중세부터 근대까지의 회화와 고대 조각을 전시하며, 회랑에는 메디치가의 고대 조각 소장품도 놓여 있습니다.",
        "zh": "16世纪中叶，佛罗伦萨统治者科西莫一世·德·美第奇委托乔尔乔·瓦萨里建造一座集中市政机构（“乌菲齐”，意为办公室）的建筑；乌菲齐宫于1560年至1580年间建成。此后，宫殿用于收藏托斯卡纳大公的艺术品；经安娜·玛丽亚·路易莎·德·美第奇于1737年的遗赠，博物馆在彼得罗·莱奥波尔多大公时期于1769年向公众开放。如今展厅位于建筑的第一、二层，展出从中世纪到近代的绘画及古代雕塑，走廊中也陈列着美第奇家族收藏的古代雕塑。"
      },
