      "id": "global-64",
      "key": "피렌체 베키오 다리 & 아르노 강 (Ponte Vecchio)",
      "city": "피렌체, 이탈리아",
      "priority": "optional-italy",
      "kind": "global-landmark",
      "history": {
        "en": "Ponte Vecchio stands at an Arno crossing dating to Roman Florentia; after the flood of 1333, a more stable replacement was built in 1345. Its three arches are lined with masonry shops, and in 1593 goldsmiths’ workshops replaced the former butchers and fishmongers. In 1565 Giorgio Vasari built the Vasari Corridor above the shops for the Medici, and the bridge was the only one in Florence left intact during the 1944 retreat.",
        "ja": "ベッキオ橋は、古代ローマ都市フロレンティアの時代からのアルノ川渡河地点にあります。1333年の洪水の後、より頑丈な橋が計画され、1345年に完成しました。三つのアーチの両側には石造りの店舗が並び、1593年には旧来の肉屋や魚屋に代わって金細工店が入りました。1565年、ジョルジョ・ヴァザーリはメディチ家のために店舗の上にヴァザーリ回廊を造り、橋は1944年の撤退時にフィレンツェで唯一破壊を免れました。",
        "ko": "베키오 다리는 고대 로마 시대의 아르노 강 도하 지점에 자리하며, 1333년 홍수 뒤 더 견고한 다리를 새로 짓기로 해 1345년에 세워졌습니다. 양옆의 석조 상점이 이어진 세 개의 아치형 다리는 오늘날에도 강을 건너며, 1593년에는 정육점·생선가게를 대신해 금세공 상점들이 들어섰습니다. 1565년 조르조 바사리가 메디치 가문을 위해 상점 위에 바사리 회랑을 만들었고, 1944년 퇴각 중 파괴되지 않은 피렌체의 유일한 다리로 남았습니다.",
        "zh": "老桥位于古罗马弗洛伦蒂亚时期的阿尔诺河渡河处；1333年洪水后，人们决定建造一座更稳固的新桥，并于1345年建成。桥由三个拱洞构成，两侧排列着石砌店铺；1593年，金匠铺取代了原有的肉铺和鱼铺。1565年，乔尔乔·瓦萨里受美第奇家族委托，在店铺上方修建瓦萨里走廊；1944年撤退期间，它是佛罗伦萨唯一未被毁坏的桥梁。"
      },
