      "id": "global-65",
      "key": "베네치아 두칼레 궁전 & 탄식의 다리 (Doge's Palace)",
      "city": "Venice, Italy",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The Doge’s Palace traces its origins to the 9th century, when Venice was emerging as an autonomous centre; in the 12th century Doge Sebastiano Ziani replaced the earlier structure with a palace open to the city, housing government and judicial institutions. The building combines Gothic with Renaissance and Mannerist elements, and Renaissance features were introduced in rebuilding after a fire in 1483. In the 17th century the Bridge of Sighs connected the palace to the New Prisons; completed in 1614, it contains two parallel corridors enclosed by walls and a roof.",
        "ja": "ドゥカーレ宮殿の起源は、ヴェネツィアが自治的な中心地として台頭した9世紀にさかのぼります。12世紀にはドージェのセバスティアーノ・ツィアーニが旧建物を都市に開かれた宮殿へ建て替え、政府機関と司法機関を置きました。建物にはゴシック、ルネサンス、マニエリスムの要素が重なり、1483年の火災後の再建ではルネサンス様式が取り入れられました。17世紀に宮殿と新牢獄を結ぶため造られたため息橋は1614年に完成し、壁と屋根に囲まれた並行する二つの通路を備えています。",
        "ko": "두칼레 궁전의 기원은 베네치아가 자치 중심지로 자리 잡던 9세기로 거슬러 올라가며, 12세기에는 도제 세바스티아노 지아니가 옛 건물을 도시를 향해 열린 새 궁전으로 바꾸어 정부와 사법 기관을 두었습니다. 현재 건물에는 고딕 양식과 르네상스·매너리즘 요소가 함께 있으며, 1483년 화재 뒤 재건하면서 르네상스 양식이 더해졌습니다. 17세기에 궁전과 새 감옥을 잇는 탄식의 다리가 세워졌고, 1614년에 완공된 이 다리에는 지붕과 벽으로 둘러싸인 두 개의 나란한 통로가 있습니다.",
        "zh": "总督宫的起源可追溯到9世纪，当时威尼斯正发展为自治中心；12世纪，总督塞巴斯蒂亚诺·齐亚尼以一座面向城市开放的新宫殿取代旧建筑，并在其中设置政府和司法机构。建筑融合了哥特式、文艺复兴式和矫饰主义元素，1483年火灾后的重建又引入了文艺复兴风格。17世纪建造的叹息桥连接总督宫与新监狱，于1614年完工；桥内有两条并行、由墙壁和屋顶封闭的通道。"
      },
