      "key": "밀라노 두오모 & 빅토리오 에마누엘레 2세 (Duomo di Milano)",
      "city": "밀라노, 이탈리아",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "Construction of Milan Cathedral began in 1386 on the site of the earlier basilicas of Santa Maria Maggiore and Santa Tecla; the Veneranda Fabbrica was established in 1387 under the patronage of Gian Galeazzo Visconti to oversee the work. Built in Gothic style with Candoglia marble rather than the region’s traditional brick, the cathedral took shape over successive generations, with later periods also leaving their mark on its interior and façade. Its tall spires, marble sculpture, and stained glass are visible today; the façade doors were installed between 1909 and 1965, and remains of earlier places of worship survive in the archaeological area below.",
        "ja": "ミラノ大聖堂の建設は1386年、サンタ・マリア・マッジョーレとサンタ・テクラの旧聖堂があった場所で始まり、工事を担うヴェネランダ・ファッブリカはジャン・ガレアッツォ・ヴィスコンティの後援で1387年に設立されました。ロンバルディア地方で伝統的に使われた煉瓦ではなくカンドリア産大理石を用いたゴシック様式の建築は、世代を超えて進められ、後の時代には内部や正面にも改変が加わりました。現在は高い尖塔、大理石彫刻、ステンドグラスが見られ、正面の扉は1909～1965年に設置され、地下の考古学エリアには以前の礼拝堂の遺構が残っています。",
        "ko": "밀라노 대성당 건설은 1386년 고대 산타 마리아 마조레와 산타 테클라 성당이 있던 자리에 시작됐으며, 1387년 잔 갈레아초 비스콘티의 후원으로 공사를 맡은 베네란다 파브리카가 설립됐습니다. 롬바르디아의 전통적인 벽돌 대신 칸도글리아 대리석을 쓰고 고딕 양식으로 지으면서, 여러 세대에 걸쳐 공사가 이어졌고 후대에는 내부와 정면에도 시대별 변화가 더해졌습니다. 오늘날에는 높은 첨탑과 대리석 조각, 스테인드글라스를 볼 수 있으며, 정면의 문은 1909~1965년에 설치됐고 대성당 아래 고고학 구역에는 이전 예배당들의 유적이 남아 있습니다.",
        "zh": "米兰大教堂于1386年在圣玛丽亚马焦雷和圣特克拉两座早期教堂所在之处动工；负责工程的韦内兰达大教堂建造机构于1387年在詹·加莱亚佐·维斯孔蒂的支持下成立。建筑采用哥特式风格和坎多利亚大理石，而非伦巴第地区传统的砖材，工程历经数代，后来的时期也为内部与正立面留下了变化。如今可见高耸的尖塔、大理石雕刻和彩色玻璃窗；正立面的门于1909至1965年间安装，地下考古区还保存着早期礼拜建筑的遗迹。"
      },
