      "id": "global-68",
      "key": "피사 사탑 & 기적의 광장 (Piazza dei Miracoli)",
      "city": "피사",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "The medieval complex began with the foundation of a new cathedral in 1064; between the 11th and 14th centuries, the cathedral, baptistery, bell tower and cemetery were built close together to form the ensemble seen today. UNESCO describes its interplay of marble and mosaics, arched galleries, domes and the leaning tower as an important expression of Pisan Romanesque architecture. The tower is the cathedral’s bell tower, not a defensive structure; inside the cathedral, later decoration reflects a history that included a fire, and the wooden coffered ceiling replaced the original exposed roof trusses in the 17th century.",
        "ja": "この中世建築群は1064年の新大聖堂の創建に始まり、11～14世紀に大聖堂、洗礼堂、鐘楼、墓地が近接して建てられ、現在の一体的な景観を形づくりました。ユネスコは、大理石とモザイク、アーチ状の回廊、ドーム、傾いた鐘楼の組み合わせを、ピサ・ロマネスク様式を示す重要な景観として説明しています。斜塔は防衛施設ではなく大聖堂の鐘楼で、大聖堂内部には火災を経た装飾があり、木造格天井は17世紀に当初の露出した屋根小屋組に取って代わりました。",
        "ko": "광장의 중세 건축군은 1064년 새 대성당 건립과 함께 시작됐으며, 11~14세기에 대성당·세례당·종탑·묘지가 가까이 세워져 지금의 구성을 이루었습니다. UNESCO는 대리석과 모자이크, 아치형 회랑, 돔과 기울어진 종탑이 어우러진 경관을 피사 로마네스크 양식의 중요한 사례로 설명합니다. 사탑은 방어용 건물이 아니라 대성당의 종탑이며, 대성당 내부에서는 화재 뒤의 장식과 17세기에 원래 트러스 지붕을 대신한 목조 격자천장을 볼 수 있습니다.",
        "zh": "这组中世纪建筑始于1064年新建大教堂；11至14世纪间，大教堂、洗礼堂、钟楼和墓地相邻建成，形成今天的整体格局。联合国教科文组织将大理石与马赛克、拱廊、穹顶和倾斜钟楼交织的景观视为比萨罗曼式建筑的重要体现。斜塔是大教堂的钟楼，并非防御建筑；大教堂内部可见经历火灾后形成的装饰，木制格状天花板则在17世纪取代了原先裸露的屋架。"
      },
