      "key": "아말피 해안 & 포지타노 (Amalfi Coast & Positano)",
      "city": "아말피, 이탈리아",
      "priority": "catalog-wide",
      "kind": "global-landmark",
      "history": {
        "en": "UNESCO notes prehistoric settlement evidence from Palaeolithic and Mesolithic finds at Positano, a Roman colony in the 4th century, and intensive settlement from the early Middle Ages. Several historic centres flourished during the Amalfi maritime republic’s economic power in the 9th–11th centuries, leaving architecture and art shaped by exchanges between East and West. Today, narrow lanes and stairs follow the steep terrain, while terraced vineyards and orchards, supported by dry-stone walls, remain visible along the slopes.",
        "ja": "ユネスコによると、ポジターノで見つかった旧石器時代・中石器時代の遺物は先史時代からの居住を示し、この地域は4世紀にローマの植民地となり、中世初期から集中的に人が住むようになった。9〜11世紀にアマルフィ海洋共和国が経済的に繁栄すると、沿岸の歴史的中心地も発展し、その建築や芸術には東西交流の影響が残った。現在も急斜面に沿う狭い路地や階段、石積みの擁壁に支えられたブドウ畑や果樹園の段々畑を見ることができる。",
        "ko": "유네스코는 포지타노에서 발견된 구석기·중석기 유물을 근거로 해안에 선사시대부터 사람이 살았으며, 4세기에는 로마 식민지가 되었고 중세 초부터 정착이 활발해졌다고 설명한다. 9~11세기 아말피 해상 공화국의 경제적 번영기에 여러 역사 마을이 성장했고, 건축과 예술에는 동서 교류의 영향이 남았다. 오늘날 해안에서는 급경사 지형을 따라 난 좁은 골목과 계단, 포도밭·과수원 계단식 경작지와 이를 받치는 건식 석벽을 볼 수 있다.",
        "zh": "联合国教科文组织指出，在波西塔诺发现的旧石器时代和中石器时代遗存表明海岸地区在史前时期已有居民；这里于4世纪成为罗马殖民地，并从中世纪早期起得到密集定居。9至11世纪阿马尔菲海上共和国经济兴盛，沿岸多个历史中心随之发展，其建筑与艺术留下了东西交流的影响。如今仍可见顺应陡峭地势修建的狭窄街巷和阶梯，以及由干砌石墙支撑的葡萄园、果园梯田。"
      },
