      "history": {
        "en": "The Baths of Caracalla, known in antiquity as the Thermae Antoninianae, were built in southern Rome on the initiative of Emperor Caracalla, son of Septimius Severus; the central building opened in AD 216. This large imperial bath complex served not only bathing but also exercise, bodily care, walking, and study; its central sequence comprised the caldarium, tepidarium, frigidarium, and natatio, with paired gyms and changing rooms arranged symmetrically at the sides. The remains include high-standing walls and traces of underground service passages, while the earlier Hadrianic-period Domus of Vigna Guidi and its frescoes, restored in 2022, reveal an earlier layer of the site.",
        "ja": "古代に「テルマエ・アントニニアナエ」と呼ばれたカラカラ浴場は、セプティミウス・セウェルスの子カラカラ帝の主導でローマ南部に建設され、中央棟は西暦216年に開館した。大規模な帝国浴場は入浴だけでなく、運動、身体の手入れ、散策、学習にも使われ、中央部にはカルダリウム、テピダリウム、フリギダリウム、ナタティオが軸上に並び、両側に運動場と更衣室が対称に配置された。遺構には高く残る壁体や地下の設備通路の痕跡があり、浴場より古いハドリアヌス時代のヴィーニャ・グイディ邸宅と、2022年に修復された壁画もこの場所の先行する歴史を伝えている。",
        "ko": "카라칼라 욕장(당시 Thermae Antoninianae)은 세베루스의 아들 카라칼라 황제의 주도로 로마 남부에 세워졌으며, 중앙 건물은 서기 216년에 개관했다. 목욕뿐 아니라 운동·신체 관리·산책·독서에 쓰인 대형 제국 목욕장이었고, 중심부에는 칼다리움·테피다리움·프리기다리움·나타티오가 축을 따라 배치됐으며 양옆에 운동장과 탈의실이 대칭으로 놓였다. 현재 유적에서는 높은 벽체와 지하 설비 통로의 흔적을 볼 수 있으며, 욕장보다 앞선 아드리아누스 시대의 비냐 구이디 주거지와 2022년 복원된 벽화도 이 유적의 여러 시대를 보여 준다.",
        "zh": "卡拉卡拉浴场在古代称为“安东尼努斯浴场”，由塞普蒂米乌斯·塞维鲁之子卡拉卡拉皇帝主持，在罗马南部兴建；中央建筑于公元216年启用。这座大型帝国浴场不仅用于沐浴，也供人运动、护理身体、散步和学习；中央区域沿轴线依次设有热水浴室、温水浴室、冷水浴室和游泳池，两侧对称布置健身场与更衣室。遗址现存高耸墙体及地下服务通道的遗迹；早于浴场建造的哈德良时期维尼亚·圭迪宅邸及其于2022年修复的壁画，也呈现了此地更早的历史层次。"
      },
