      "kind": "rome-guide-spot",
      "history": {
        "en": "From the 15th century, the area became a commercial centre, with foreign residents and lodging drawn by Spanish and French diplomatic representatives. Designed by Francesco De Sanctis, the steps were built in 1723–1726 to link the hill district with a strong French presence to the Spanish quarter below; they were inaugurated for the 1725 Jubilee. The travertine staircase rises in winding flights with balustrades; above it stands the church of Trinità dei Monti, founded in 1495, while the square’s centre holds Pietro Bernini’s boat-shaped Barcaccia Fountain, made in 1626–1629. The steps underwent a full restoration in 1995, followed by a restoration begun in 2015 and completed in 2016.",
        "ja": "15世紀以降、この界隈にはスペインとフランスの外交代表部に引き寄せられた外国人居住者や宿が集まり、商業の中心地となりました。フランチェスコ・デ・サンクティス設計の階段は1723～1726年に造られ、フランス色の強い丘の上の地区と下方のスペイン人街を結び、1725年の聖年に開通しました。トラバーチン石の階段は曲線を描く踊り場と手すりを備え、頂上には1495年創建のトリニタ・デイ・モンティ教会、広場の中央にはピエトロ・ベルニーニ作の船形噴水「バルカッチャ」（1626～1629年）があります。階段は1995年に全面修復され、2015年に始まった修復は2016年に完了しました。",
        "ko": "15세기부터 이 일대는 스페인·프랑스 측 대표부와 외국인 숙소가 모이면서 상업 중심지로 자리 잡았습니다. 프란체스코 데 산크티스가 설계한 계단은 1723~1726년에 조성되어 프랑스 영향이 강한 언덕 위 구역과 아래쪽 스페인 거류지를 연결했으며, 1725년 희년을 맞아 개장했습니다. 트라베르틴 석재 계단은 굽이치는 단과 난간으로 언덕을 오르며, 위쪽에는 1495년에 설립된 트리니타 데이 몬티 성당, 광장 중앙에는 피에트로 베르니니가 1626~1629년에 만든 배 모양의 바르카차 분수가 있습니다. 계단은 1995년에 전면 복원됐고, 2015년 시작된 복원은 2016년에 마무리됐습니다.",
        "zh": "自15世纪起，西班牙和法国的外交代表机构吸引外国居民与旅店聚集于此，使这一带成为商业中心。由弗朗切斯科·德·桑克蒂斯设计的阶梯建于1723至1726年，连接法国势力较强的山上街区与下方的西班牙人聚居区，并于1725年禧年期间启用。石灰华阶梯以曲折的梯段和栏杆顺坡而上；顶部是1495年创建的山上圣三一教堂，广场中央则有彼得罗·贝尔尼尼于1626至1629年建造的船形“破船喷泉”。阶梯于1995年全面修复，2015年开始的另一轮修复于2016年完成。"
      },
