      "kind": "rome-guide-spot",
      "history": {
        "en": "The Vatican Museums house art, archaeological and ethnological collections gathered by the popes over centuries, as well as historic rooms of the Apostolic Palace. The Sistine Chapel takes its name from Pope Sixtus IV, who had the old Cappella Magna restored in 1477–1480. Painters including Perugino, Botticelli and Ghirlandaio decorated its walls in 1481–1482; under Julius II, Michelangelo painted the ceiling’s central Genesis scenes, completing them in 1512. On the altar wall, Michelangelo’s Last Judgment (1536–1541) shows Christ at the center of a sweeping circular movement of figures.",
        "ja": "バチカン美術館には、歴代教皇が何世紀にもわたって集めた美術・考古学・民族学のコレクションと、使徒宮殿の歴史的な部屋が収められている。システィーナ礼拝堂の名は教皇シクストゥス4世に由来し、同教皇は1477～1480年に旧カペラ・マグナの修復を命じた。1481～1482年にはペルジーノ、ボッティチェッリ、ギルランダイオらが壁画を制作し、ユリウス2世の時代にミケランジェロが天井中央部の創世記の場面を描き、1512年に完成させた。祭壇壁にはミケランジェロの《最後の審判》（1536～1541年）があり、キリストを中心に人物が大きく旋回する構図をなしている。",
        "ko": "바티칸 박물관은 교황들이 여러 세기에 걸쳐 모은 미술·고고학·민족인류학 컬렉션과 사도궁의 역사적인 방들을 함께 품고 있다. 시스티나 성당은 교황 식스토 4세의 이름을 따랐으며, 그는 1477~1480년 옛 카펠라 마그나의 복원을 명했다. 1481~1482년 페루지노·보티첼리·기르란다요 등 화가들이 벽화를 그렸고, 율리우스 2세 때 미켈란젤로는 천장 중앙에 창세기 장면들을 그려 1512년 마쳤다. 제단 벽에는 미켈란젤로의 《최후의 심판》(1536~1541)이 있으며, 그리스도를 중심으로 인물들이 큰 회전형 구도를 이룬다.",
        "zh": "梵蒂冈博物馆收藏着历代教皇数百年来汇集的艺术、考古学和民族学藏品，也包括使徒宫内的历史房间。西斯廷礼拜堂以教皇西克斯图斯四世命名；他于1477至1480年下令修复旧大礼拜堂（Cappella Magna）。1481至1482年，佩鲁吉诺、波提切利、吉兰达约等画家绘制了墙面壁画；在尤利乌斯二世时期，米开朗基罗绘制天顶中央的《创世纪》场景，并于1512年完成。祭坛墙上可见米开朗基罗创作于1536至1541年的《最后的审判》，画面以基督为中心，众人形成大幅旋转式构图。"
      },
