      "kind": "rome-guide-spot",
      "history": {
        "en": "The name Trastevere comes from the Latin trans Tiberim (“beyond the Tiber”) and was also used for an Augustan-era district. Rome’s official tourism site says the city’s center developed on the river’s opposite bank. The Basilica of Santa Maria in Trastevere was rebuilt under Pope Innocent II, and many surviving parts date to the 12th century. Inside, the three-aisled church has ancient granite columns; its apse includes Pietro Cavallini’s 1291 mosaics depicting the Life of the Virgin.",
        "ja": "トラステヴェレという名称はラテン語の trans Tiberim（テヴェレ川の向こう）に由来し、古代アウグストゥス時代の地区名としても使われました。ローマ市の公式観光サイトによると、都市の中心は川の対岸に発展しました。地区内のサンタ・マリア・イン・トラステヴェレ聖堂は教皇インノケンティウス2世の時代に再建され、現存部分の多くは12世紀のものです。内部では三廊式の空間と古代の花崗岩円柱を見られ、後陣にはピエトロ・カヴァッリーニによる1291年の聖母伝のモザイクがあります。",
        "ko": "트라스테베레라는 이름은 라틴어 trans Tiberim(테베레강 건너편)에서 왔으며, 고대 아우구스투스 시대의 지역명으로도 쓰였습니다. 로마의 도시 중심지는 강 건너편에 발달했다고 로마 공식 관광 사이트는 설명합니다. 이 지역의 산타 마리아 인 트라스테베레 대성당은 교황 인노첸시오 2세 재위기에 재건되었고, 현존 건축물의 상당 부분은 12세기에 속합니다. 내부의 세 개 회랑과 고대 화강암 기둥을 볼 수 있으며, 후진에는 피에트로 카발리니가 1291년에 만든 성모 생애 모자이크가 있습니다.",
        "zh": "特拉斯提弗列的名称源自拉丁语 trans Tiberim（台伯河对岸），也曾是奥古斯都时期的地区名称。罗马官方旅游网站介绍，城市中心曾在河对岸发展。区内的圣母圣殿在教宗英诺森二世在位期间重建，现存建筑的许多部分可追溯至12世纪。殿内可见三廊式空间和古代花岗岩柱，后殿则有彼得罗·卡瓦利尼于1291年创作的圣母生平马赛克。"
      },
