      "id": "rome-testaccio",
      "spotId": "testaccio",
      "city": "Rome",
      "priority": "planned-italy",
      "kind": "rome-guide-spot",
      "history": {
        "en": "Broken amphorae discarded from ancient Rome’s river port of Emporium from the 1st century AD formed the artificial hill Mons Testaceus (Monte Testaccio). In the late 19th century, the plain of Testaccio was developed for workers in industries along Via Ostiense; its former slaughterhouse was built in 1888–1891 and is now used as a cultural venue while retaining its industrial-architecture character. The neighborhood’s historic market long occupied Piazza Testaccio, then moved to a new site on Via Galvani in 2015 after the square was redeveloped.",
        "ja": "古代ローマの河港エンポリウムから出たアンフォラの破片が、西暦1世紀以降ここに廃棄され、人工の丘モンス・テスタケウス（モンテ・テスタッチョ）を形づくりました。19世紀末、テスタッチョの平地はヴィア・オスティエンセ沿いの産業で働く人々の居住地として開発され、旧屠畜場は1888～1891年に建設されました。産業建築の面影を残す旧屠畜場は現在、文化施設として使われ、地区の歴史ある市場は長年ピアッツァ・テスタッチョに置かれた後、広場の再整備を経て2015年にヴィア・ガルバーニの新しい場所へ移りました。",
        "ko": "고대 로마의 강항구 엠포리움에서 나온 깨진 암포라 조각이 서기 1세기부터 이곳에 버려져 인공 언덕 몬스 테스타체우스(몬테 테스타초)를 이루었습니다. 19세기 말 테스타초 평지는 비아 오스티엔세 일대 산업 노동자들의 주거지로 개발되었고, 옛 도축장은 1888~1891년에 세워져 현재는 산업 건축의 흔적을 간직한 문화 공간으로 쓰입니다. 지역의 역사적 시장은 오랫동안 피아차 테스타초에 있었으며, 광장 정비 뒤 2015년 비아 갈바니의 새 자리로 옮겨졌습니다.",
        "zh": "古罗马河港埃姆波里乌姆被丢弃的陶罐碎片，自公元1世纪起在此堆积，形成了人工土丘蒙斯·特斯塔切乌斯（蒙特·泰斯塔乔）。19世纪末，特斯塔乔平地被开发为维亚·奥斯蒂恩塞沿线产业工人的居住区；旧屠宰场建于1888至1891年，如今作为文化场所使用，仍保留工业建筑特色。当地历史悠久的市场长期设在特斯塔乔广场，广场整修后于2015年迁至维亚·加尔巴尼的新址。"
      },
