        "ko": "부르봉 왕 카를로 3세의 뜻에 따라 건축가 조반니 안토니오 메드라노와 안젤로 카라살레가 설계·건립을 맡았고, 산 카를로 극장은 1737년 11월 4일 문을 열었습니다. 18세기에는 페르디난도 푸가가 객석을 개수했으며, 19세기 안토니오 니콜리니의 재건 과정에서도 말굽형 객석 배치가 이어졌습니다. 무대 앞쪽 개구부(프로시니엄) 안쪽에는 ‘시간과 시간들’을 나타내는 부조가 지금도 남아 있습니다.",
